	/** 
	 * jumpstart the process by instantiating2 Prediction
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		predictionId = PredictionService.getPredictionInstance()
		.createPrediction( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		PredictionService.getPredictionInstance()
				.createPrediction( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.predictionSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Prediction : " + successValue.getPredictionId());
							  if (successValue.getPredictionId().equals(predictionId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfPredictionList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Prediction test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on prediction consumed")
					);
			subscriber.predictionSubscribe( predictionId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Prediction : " + successValue.getPredictionId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfPredictionList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on prediction for predictionId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Prediction. 
	 */
	protected Prediction read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Prediction" );

		Prediction entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Prediction with primary key" );
		msg.append( predictionId );
		
		PredictionFetchOneSummary fetchOneSummary = new PredictionFetchOneSummary( predictionId );

		try {
			entity = PredictionService.getPredictionInstance().getPrediction( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Prediction " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Prediction.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Prediction." );

		StringBuilder msg = new StringBuilder( "Failed to update a Prediction : " );        
		Prediction entity = read();
		UpdatePredictionCommand command = generateUpdateCommand();
		command.setPredictionId(entity.getPredictionId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Prediction." );

			// for use later on...
			predictionId = entity.getPredictionId();

			PredictionService proxy = PredictionService.getPredictionInstance();  

			proxy.updatePrediction( command ).get();

			LOGGER.info( "-- Successfully saved Prediction - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + predictionId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Prediction.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Prediction." );

		Prediction entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Prediction with id " + predictionId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Prediction with id " + predictionId );

			throw e;
		}

		try{
			PredictionService.getPredictionInstance().delete( new DeletePredictionCommand( entity.getPredictionId() ) ).get();
			LOGGER.info( "-- Successfully deleted Prediction with id " + predictionId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Prediction with id " + predictionId );

			throw e;
		}
	}

	/**
	 * get all Predictions.
	 */
	protected List<Prediction> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Predictions:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Prediction : " );        
		List<Prediction> collection  = new ArrayList<>();

		try {
			// call the static get method on the PredictionService
			collection = PredictionService.getPredictionInstance().getAllPrediction();
			assertNotNull( collection, "An Empty collection of Prediction was incorrectly returned.");
			
			// Now print out the values
			Prediction entity = null;            
			Iterator<Prediction> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getPredictionId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

